using System;
using System.Data;
using System.Windows.Forms;

namespace View
{
    // LOGIN SCREEN. Asks for a username and password, checks them and opens the menu.
    // It calls the UserService over HTTP instead of creating a UserController.
    public partial class FormLogin : Form
    {
        // Proxy generated by Visual Studio from the service. Calling a method on it
        // sends a SOAP request and waits for the answer.
        private UserServiceRef.UserService userService = new UserServiceRef.UserService();

        public FormLogin()
        {
            InitializeComponent();
        }

        private void btnLogin_Click(object sender, EventArgs e)
        {
            try
            {
                // Both fields are required.
                if (string.IsNullOrWhiteSpace(txtUsername.Text))
                {
                    MessageBox.Show("Please enter your username.");
                    return;
                }
                if (string.IsNullOrWhiteSpace(txtPassword.Text))
                {
                    MessageBox.Show("Please enter your password.");
                    return;
                }

                // The service cannot return a User object, so it sends a table with one
                // row when the credentials are valid and an empty one when they are not.
                DataTable table = userService.Login(txtUsername.Text, txtPassword.Text);

                if (table.Rows.Count == 0)
                {
                    MessageBox.Show("Invalid username or password.");
                    return;
                }

                // Row zero is safe because the username is unique in TabUser.
                DataRow row = table.Rows[0];

                LoggedUser loggedUser = new LoggedUser
                {
                    UID = (int)row["UID"],
                    UserName = row["UserName"].ToString(),
                    UserLevel = (int)row["UserLevel"]
                };

                FormMenu menu = new FormMenu(loggedUser);
                menu.Show();
                this.Hide();
            }
            catch (Exception ex)
            {
                // An error here is usually the service not running, not a wrong password.
                MessageBox.Show("Error during login: " + ex.Message);
            }
        }
    }
}